INSERT INTO ui.perspectivequery (iperspectivequeryid, vcquery, vctablename, formattingrequiered, runonanalytics) VALUES (41, 'select ilivemessageid as "ILiveMessageID", vcmsgid as "UniqueID", vcclassname as "Class", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as "Time",
dobservationamount as "Amount", score as "Score",  cast(result->''score''->>''bpass'' as text)as "FRMPass", vcpayeraccountexternalid as "Payer Account", vcpayeraddr as "PayerVPA",
